-- Same-runner, root-fenced subagents. Stop every pre-0064 writer before independent migration.

-- No external execution, physical deletion, credential sharing, Redis authority or completion is added.

SET @subagent_previous_gcml=@@SESSION.group_concat_max_len;

SET SESSION group_concat_max_len=1048576;

SET @skill_registry_triggers_ok=(
  (SELECT COUNT(*)=14 FROM information_schema.tables WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%'))
  AND (SELECT COUNT(*)=0 FROM information_schema.partitions WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%') AND partition_name IS NOT NULL)
  AND (SELECT COUNT(*)=818 AND SUM(trigger_name LIKE 'trg_tenant_webhook%')=23 AND SUM(OCTET_LENGTH(CONCAT_WS('~',event_object_table,trigger_name,action_timing,event_manipulation,action_orientation,IFNULL(action_condition,'<NULL>'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(action_statement,'[[:space:]]',''),CHAR(96),''),'_utf8mb4','')))))+COUNT(*)-1<=@@SESSION.group_concat_max_len FROM information_schema.triggers WHERE trigger_schema=DATABASE())
  AND SHA2(CONCAT_WS('::',
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,engine,table_collation,row_format,create_options) ORDER BY table_name SEPARATOR '|'),256) FROM information_schema.tables WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%')),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,LPAD(ordinal_position,3,'0'),column_name,column_type,is_nullable,IFNULL(column_default,'<NULL>'),extra,IFNULL(character_set_name,'-'),IFNULL(collation_name,'-'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(IFNULL(generation_expression,''),'[[:space:]]',''),CHAR(96),''),'_utf8mb4',''))) ORDER BY table_name,ordinal_position SEPARATOR '|'),256) FROM information_schema.columns WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%')),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,index_name,LPAD(seq_in_index,3,'0'),column_name,non_unique,index_type,IFNULL(collation,'-'),IFNULL(sub_part,'-'),IFNULL(nullable,'-')) ORDER BY table_name,index_name,seq_in_index SEPARATOR '|'),256) FROM information_schema.statistics WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%')),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,constraint_name,constraint_type,IFNULL(enforced,'-')) ORDER BY table_name,constraint_name SEPARATOR '|'),256) FROM information_schema.table_constraints WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%')),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',constraint_name,LOWER(REPLACE(REPLACE(REGEXP_REPLACE(check_clause,'[[:space:]]',''),CHAR(96),''),'_utf8mb4',''))) ORDER BY constraint_name SEPARATOR '|'),256) FROM information_schema.check_constraints WHERE constraint_schema=DATABASE() AND (constraint_name='chk_mcp_owner' OR constraint_name='chk_tenant_webhook_slot_state')),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,constraint_name,referenced_table_name,update_rule,delete_rule) ORDER BY table_name,constraint_name SEPARATOR '|'),256) FROM information_schema.referential_constraints WHERE constraint_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%')),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,constraint_name,LPAD(ordinal_position,3,'0'),column_name,referenced_table_name,referenced_column_name) ORDER BY table_name,constraint_name,ordinal_position SEPARATOR '|'),256) FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%') AND referenced_table_name IS NOT NULL),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',event_object_table,trigger_name,action_timing,event_manipulation,action_orientation,IFNULL(action_condition,'<NULL>'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(action_statement,'[[:space:]]',''),CHAR(96),''),'_utf8mb4',''))) ORDER BY event_object_table,trigger_name SEPARATOR '|'),256) FROM information_schema.triggers WHERE trigger_schema=DATABASE())
  ),256)='c6d6e4fb00c7a7dcb87fa91f5cfeb78b7dfdef08cae7ff2e47aaec8e597704f7'
);

SET @subagent_marker_ok=(SELECT COUNT(*)=1 FROM schema_migrations WHERE BINARY name=BINARY '0063_tenant_webhooks.sql');

SET @migration_sql=IF(@skill_registry_triggers_ok=1 AND @subagent_marker_ok=1,'SELECT 1','SELECT 1 FROM __invalid_subagent_predecessor__');

PREPARE migration_stmt FROM @migration_sql;

EXECUTE migration_stmt;

DEALLOCATE PREPARE migration_stmt;

CREATE TABLE subagent_root_turns (
 root_key CHAR(64) NOT NULL, root_session_id VARCHAR(64) NOT NULL, root_turn_id VARCHAR(64) NOT NULL,
 tenant_id VARCHAR(128) NOT NULL,user_id VARCHAR(128) NOT NULL,root_fence BIGINT UNSIGNED NOT NULL,state VARCHAR(32) NOT NULL,
 active_session_id VARCHAR(64) GENERATED ALWAYS AS (IF(state IN ('active','closing'),root_session_id,NULL)) STORED,
 writer_connection_id BIGINT UNSIGNED NULL,writer_session_id VARCHAR(64) NULL,writer_mode VARCHAR(16) NULL,writer_fence BIGINT UNSIGNED NULL,
 record_sha256 CHAR(64) NOT NULL,record_json JSON NOT NULL,
 PRIMARY KEY(root_key),UNIQUE KEY uk_subagent_root_turn(root_session_id,root_turn_id),UNIQUE KEY uk_subagent_active_root(active_session_id),
 KEY idx_subagent_root_owner(tenant_id,user_id,root_key),
 CONSTRAINT chk_subagent_root_state CHECK(state IN ('active','closing','terminal','outcome_unknown')),
 CONSTRAINT chk_subagent_writer CHECK((writer_connection_id IS NULL AND writer_session_id IS NULL AND writer_mode IS NULL AND writer_fence IS NULL) OR (writer_connection_id IS NOT NULL AND writer_session_id IS NOT NULL AND writer_mode IN ('business','repair','delete') AND writer_fence IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE subagent_tasks (
 task_id VARCHAR(64) NOT NULL,root_key CHAR(64) NOT NULL,tenant_id VARCHAR(128) NOT NULL,user_id VARCHAR(128) NOT NULL,
 parent_session_id VARCHAR(64) NOT NULL,parent_call_item_id VARCHAR(64) NOT NULL,child_session_id VARCHAR(64) NOT NULL,
 depth INT UNSIGNED NOT NULL,status VARCHAR(32) NOT NULL,record_sha256 CHAR(64) NOT NULL,record_json JSON NOT NULL,
 PRIMARY KEY(task_id),UNIQUE KEY uk_subagent_child(child_session_id),UNIQUE KEY uk_subagent_parent_call(parent_call_item_id),
 KEY idx_subagent_tasks_root(root_key,depth,task_id),KEY idx_subagent_tasks_owner(tenant_id,user_id,task_id),
 CONSTRAINT fk_subagent_task_root FOREIGN KEY(root_key) REFERENCES subagent_root_turns(root_key) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT chk_subagent_task_state CHECK(status IN ('reserved','running','completed','failed','interrupted','outcome_unknown'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TABLE subagent_budget_entries (
 entry_id CHAR(64) NOT NULL,root_key CHAR(64) NOT NULL,tenant_id VARCHAR(128) NOT NULL,user_id VARCHAR(128) NOT NULL,
 session_id VARCHAR(64) NOT NULL,turn_id VARCHAR(64) NOT NULL,kind VARCHAR(32) NOT NULL,step INT UNSIGNED NOT NULL,call_item_id VARCHAR(64) NULL,
 state VARCHAR(32) NOT NULL,ordinal BIGINT UNSIGNED NOT NULL,record_sha256 CHAR(64) NOT NULL,record_json JSON NOT NULL,
 PRIMARY KEY(entry_id),UNIQUE KEY uk_subagent_budget_ordinal(root_key,ordinal),
 KEY idx_subagent_budget_member(root_key,session_id,turn_id,kind,step),KEY idx_subagent_budget_owner(tenant_id,user_id,entry_id),
 CONSTRAINT fk_subagent_budget_root FOREIGN KEY(root_key) REFERENCES subagent_root_turns(root_key) ON DELETE RESTRICT ON UPDATE RESTRICT,
 CONSTRAINT chk_subagent_budget_state CHECK(state IN ('admitted','settled','outcome_unknown')),
 CONSTRAINT chk_subagent_budget_kind CHECK((kind='provider_step' AND call_item_id IS NULL) OR (kind='tool_call' AND call_item_id IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

CREATE TRIGGER trg_subagent_root_turns_bi BEFORE INSERT ON subagent_root_turns FOR EACH ROW BEGIN IF (EXISTS(SELECT 1 FROM sessions s WHERE s.session_id=NEW.root_session_id AND BINARY s.session_id=BINARY NEW.root_session_id AND BINARY s.tenant_id=BINARY NEW.tenant_id AND BINARY s.user_id=BINARY NEW.user_id AND s.deleted_at_ms IS NULL AND s.fence_token>=NEW.root_fence FOR SHARE) AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.rootSessionId'))=BINARY NEW.root_session_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.rootTurnId'))=BINARY NEW.root_turn_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.principal.tenantId'))=BINARY NEW.tenant_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.principal.userId'))=BINARY NEW.user_id AND JSON_EXTRACT(NEW.record_json,'$.rootFence')=NEW.root_fence AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state'))=BINARY NEW.state AND NEW.root_key=SHA2(CONCAT('["subagent-root-v1",',JSON_QUOTE(NEW.root_session_id),',',JSON_QUOTE(NEW.root_turn_id),']'),256) AND NEW.state='active' AND NEW.writer_connection_id IS NULL AND JSON_EXTRACT(NEW.record_json,'$.steps')=0 AND JSON_EXTRACT(NEW.record_json,'$.toolCalls')=0 AND JSON_EXTRACT(NEW.record_json,'$.taskCount')=0) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Subagent root admission is invalid'; END IF; END;

CREATE TRIGGER trg_subagent_root_turns_bu BEFORE UPDATE ON subagent_root_turns FOR EACH ROW BEGIN IF ((EXISTS(SELECT 1 FROM sessions s WHERE s.session_id=NEW.root_session_id AND BINARY s.session_id=BINARY NEW.root_session_id AND BINARY s.tenant_id=BINARY NEW.tenant_id AND BINARY s.user_id=BINARY NEW.user_id AND s.deleted_at_ms IS NULL AND s.fence_token>=NEW.root_fence FOR SHARE) AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.rootSessionId'))=BINARY NEW.root_session_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.rootTurnId'))=BINARY NEW.root_turn_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.principal.tenantId'))=BINARY NEW.tenant_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.principal.userId'))=BINARY NEW.user_id AND JSON_EXTRACT(NEW.record_json,'$.rootFence')=NEW.root_fence AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state'))=BINARY NEW.state AND NEW.root_key=SHA2(CONCAT('["subagent-root-v1",',JSON_QUOTE(NEW.root_session_id),',',JSON_QUOTE(NEW.root_turn_id),']'),256) AND BINARY NEW.root_key=BINARY OLD.root_key AND BINARY NEW.root_session_id=BINARY OLD.root_session_id AND BINARY NEW.root_turn_id=BINARY OLD.root_turn_id AND BINARY NEW.tenant_id=BINARY OLD.tenant_id AND BINARY NEW.user_id=BINARY OLD.user_id AND NEW.root_fence=OLD.root_fence AND JSON_EXTRACT(NEW.record_json,'$.policy')=JSON_EXTRACT(OLD.record_json,'$.policy') AND JSON_EXTRACT(NEW.record_json,'$.authority')=JSON_EXTRACT(OLD.record_json,'$.authority') AND JSON_EXTRACT(NEW.record_json,'$.limits')=JSON_EXTRACT(OLD.record_json,'$.limits') AND JSON_EXTRACT(NEW.record_json,'$.deadlineAtMs')=JSON_EXTRACT(OLD.record_json,'$.deadlineAtMs') AND (OLD.state IN ('active','closing') OR NEW.state=OLD.state) AND (OLD.state<>'closing' OR NEW.state<>'active') AND JSON_EXTRACT(NEW.record_json,'$.effectiveDeadlineAtMs')<=JSON_EXTRACT(OLD.record_json,'$.effectiveDeadlineAtMs') AND JSON_EXTRACT(NEW.record_json,'$.steps')>=JSON_EXTRACT(OLD.record_json,'$.steps') AND JSON_EXTRACT(NEW.record_json,'$.toolCalls')>=JSON_EXTRACT(OLD.record_json,'$.toolCalls') AND JSON_EXTRACT(NEW.record_json,'$.taskCount')>=JSON_EXTRACT(OLD.record_json,'$.taskCount') AND (NEW.writer_connection_id IS NULL OR (NEW.writer_connection_id=CONNECTION_ID() AND NEW.writer_fence>=NEW.root_fence AND (BINARY NEW.writer_session_id=BINARY NEW.root_session_id OR EXISTS(SELECT 1 FROM subagent_tasks t WHERE t.child_session_id=NEW.writer_session_id AND BINARY t.child_session_id=BINARY NEW.writer_session_id AND BINARY t.root_key=BINARY NEW.root_key FOR SHARE))))) AND JSON_EXTRACT(NEW.record_json,'$.effectiveLimits.maxSteps')<=JSON_EXTRACT(OLD.record_json,'$.effectiveLimits.maxSteps') AND JSON_EXTRACT(NEW.record_json,'$.effectiveLimits.maxToolCalls')<=JSON_EXTRACT(OLD.record_json,'$.effectiveLimits.maxToolCalls') AND JSON_EXTRACT(NEW.record_json,'$.effectiveLimits.maxWallClockMs')<=JSON_EXTRACT(OLD.record_json,'$.effectiveLimits.maxWallClockMs') AND JSON_EXTRACT(NEW.record_json,'$.effectiveLimits.maxCostCNY')<=JSON_EXTRACT(OLD.record_json,'$.effectiveLimits.maxCostCNY') AND JSON_EXTRACT(NEW.record_json,'$.effectiveLimits.maxOutputTokensPerStep')<=JSON_EXTRACT(OLD.record_json,'$.effectiveLimits.maxOutputTokensPerStep')) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Subagent root update is invalid'; END IF; END;

CREATE TRIGGER trg_subagent_root_turns_bd BEFORE DELETE ON subagent_root_turns FOR EACH ROW BEGIN IF (FALSE) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Subagent proof cannot be deleted'; END IF; END;

CREATE TRIGGER trg_subagent_tasks_bi BEFORE INSERT ON subagent_tasks FOR EACH ROW BEGIN IF (EXISTS(SELECT 1 FROM subagent_root_turns r JOIN sessions s ON s.session_id=r.root_session_id AND BINARY s.session_id=BINARY r.root_session_id WHERE r.root_key=NEW.root_key AND BINARY r.root_key=BINARY NEW.root_key AND BINARY r.tenant_id=BINARY NEW.tenant_id AND BINARY r.user_id=BINARY NEW.user_id AND s.deleted_at_ms IS NULL AND BINARY s.tenant_id=BINARY NEW.tenant_id AND BINARY s.user_id=BINARY NEW.user_id AND s.fence_token>=r.root_fence FOR SHARE) AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.taskId'))=BINARY NEW.task_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.parentCallItemId'))=BINARY NEW.parent_call_item_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.parentSessionId'))=BINARY NEW.parent_session_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.childSessionId'))=BINARY NEW.child_session_id AND JSON_EXTRACT(NEW.record_json,'$.depth')=NEW.depth AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.status'))=BINARY NEW.status AND NEW.status='reserved' AND EXISTS(SELECT 1 FROM items i JOIN sessions p ON p.session_id=i.session_id WHERE i.item_id=NEW.parent_call_item_id AND BINARY i.item_id=BINARY NEW.parent_call_item_id AND BINARY i.session_id=BINARY NEW.parent_session_id AND i.type='toolCall' AND JSON_UNQUOTE(JSON_EXTRACT(i.body,'$.name'))='task' AND JSON_UNQUOTE(JSON_EXTRACT(i.body,'$.kind'))='builtin' AND JSON_TYPE(JSON_EXTRACT(i.body,'$.startedAtMs')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(i.body,'$.startedAtMs') BETWEEN 1 AND 9007199254740991 AND p.deleted_at_ms IS NULL AND BINARY p.tenant_id=BINARY NEW.tenant_id AND BINARY p.user_id=BINARY NEW.user_id FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Subagent task admission is invalid'; END IF; END;

CREATE TRIGGER trg_subagent_tasks_bu BEFORE UPDATE ON subagent_tasks FOR EACH ROW BEGIN IF ((EXISTS(SELECT 1 FROM subagent_root_turns r JOIN sessions s ON s.session_id=r.root_session_id AND BINARY s.session_id=BINARY r.root_session_id WHERE r.root_key=NEW.root_key AND BINARY r.root_key=BINARY NEW.root_key AND BINARY r.tenant_id=BINARY NEW.tenant_id AND BINARY r.user_id=BINARY NEW.user_id AND s.deleted_at_ms IS NULL AND BINARY s.tenant_id=BINARY NEW.tenant_id AND BINARY s.user_id=BINARY NEW.user_id AND s.fence_token>=r.root_fence FOR SHARE) AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.taskId'))=BINARY NEW.task_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.parentCallItemId'))=BINARY NEW.parent_call_item_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.parentSessionId'))=BINARY NEW.parent_session_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.childSessionId'))=BINARY NEW.child_session_id AND JSON_EXTRACT(NEW.record_json,'$.depth')=NEW.depth AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.status'))=BINARY NEW.status AND BINARY NEW.task_id=BINARY OLD.task_id AND BINARY NEW.root_key=BINARY OLD.root_key AND BINARY NEW.tenant_id=BINARY OLD.tenant_id AND BINARY NEW.user_id=BINARY OLD.user_id AND BINARY NEW.parent_call_item_id=BINARY OLD.parent_call_item_id AND BINARY NEW.parent_session_id=BINARY OLD.parent_session_id AND BINARY NEW.child_session_id=BINARY OLD.child_session_id AND NEW.depth=OLD.depth AND JSON_REMOVE(NEW.record_json,'$.status','$.childUsage','$.completedAtMs','$.effectiveLimits','$.effectiveDeadlineAtMs')=JSON_REMOVE(OLD.record_json,'$.status','$.childUsage','$.completedAtMs','$.effectiveLimits','$.effectiveDeadlineAtMs') AND JSON_EXTRACT(NEW.record_json,'$.effectiveDeadlineAtMs')<=JSON_EXTRACT(OLD.record_json,'$.effectiveDeadlineAtMs') AND (OLD.status IN ('reserved','running') OR NEW.record_json=OLD.record_json)) AND JSON_EXTRACT(NEW.record_json,'$.effectiveLimits.maxSteps')<=JSON_EXTRACT(OLD.record_json,'$.effectiveLimits.maxSteps') AND JSON_EXTRACT(NEW.record_json,'$.effectiveLimits.maxToolCalls')<=JSON_EXTRACT(OLD.record_json,'$.effectiveLimits.maxToolCalls') AND JSON_EXTRACT(NEW.record_json,'$.effectiveLimits.maxWallClockMs')<=JSON_EXTRACT(OLD.record_json,'$.effectiveLimits.maxWallClockMs') AND JSON_EXTRACT(NEW.record_json,'$.effectiveLimits.maxCostCNY')<=JSON_EXTRACT(OLD.record_json,'$.effectiveLimits.maxCostCNY') AND JSON_EXTRACT(NEW.record_json,'$.effectiveLimits.maxOutputTokensPerStep')<=JSON_EXTRACT(OLD.record_json,'$.effectiveLimits.maxOutputTokensPerStep')) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Subagent task update is invalid'; END IF; END;

CREATE TRIGGER trg_subagent_tasks_bd BEFORE DELETE ON subagent_tasks FOR EACH ROW BEGIN IF (FALSE) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Subagent proof cannot be deleted'; END IF; END;

CREATE TRIGGER trg_subagent_budget_entries_bi BEFORE INSERT ON subagent_budget_entries FOR EACH ROW BEGIN IF (EXISTS(SELECT 1 FROM subagent_root_turns r JOIN sessions s ON s.session_id=r.root_session_id AND BINARY s.session_id=BINARY r.root_session_id WHERE r.root_key=NEW.root_key AND BINARY r.root_key=BINARY NEW.root_key AND BINARY r.tenant_id=BINARY NEW.tenant_id AND BINARY r.user_id=BINARY NEW.user_id AND s.deleted_at_ms IS NULL AND BINARY s.tenant_id=BINARY NEW.tenant_id AND BINARY s.user_id=BINARY NEW.user_id AND s.fence_token>=r.root_fence FOR SHARE) AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.entryId'))=BINARY NEW.entry_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.sessionId'))=BINARY NEW.session_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.turnId'))=BINARY NEW.turn_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.kind'))=BINARY NEW.kind AND JSON_EXTRACT(NEW.record_json,'$.step')=NEW.step AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state'))=BINARY NEW.state AND NEW.state='admitted' AND EXISTS(SELECT 1 FROM turns t JOIN sessions s ON s.session_id=t.session_id WHERE t.turn_id=NEW.turn_id AND BINARY t.turn_id=BINARY NEW.turn_id AND BINARY t.session_id=BINARY NEW.session_id AND t.status='inProgress' AND s.deleted_at_ms IS NULL AND BINARY s.tenant_id=BINARY NEW.tenant_id AND BINARY s.user_id=BINARY NEW.user_id FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Subagent budget admission is invalid'; END IF; END;

CREATE TRIGGER trg_subagent_budget_entries_bu BEFORE UPDATE ON subagent_budget_entries FOR EACH ROW BEGIN IF (EXISTS(SELECT 1 FROM subagent_root_turns r JOIN sessions s ON s.session_id=r.root_session_id AND BINARY s.session_id=BINARY r.root_session_id WHERE r.root_key=NEW.root_key AND BINARY r.root_key=BINARY NEW.root_key AND BINARY r.tenant_id=BINARY NEW.tenant_id AND BINARY r.user_id=BINARY NEW.user_id AND s.deleted_at_ms IS NULL AND BINARY s.tenant_id=BINARY NEW.tenant_id AND BINARY s.user_id=BINARY NEW.user_id AND s.fence_token>=r.root_fence FOR SHARE) AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.entryId'))=BINARY NEW.entry_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.sessionId'))=BINARY NEW.session_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.turnId'))=BINARY NEW.turn_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.kind'))=BINARY NEW.kind AND JSON_EXTRACT(NEW.record_json,'$.step')=NEW.step AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state'))=BINARY NEW.state AND BINARY NEW.entry_id=BINARY OLD.entry_id AND BINARY NEW.root_key=BINARY OLD.root_key AND BINARY NEW.tenant_id=BINARY OLD.tenant_id AND BINARY NEW.user_id=BINARY OLD.user_id AND BINARY NEW.session_id=BINARY OLD.session_id AND BINARY NEW.turn_id=BINARY OLD.turn_id AND NEW.kind=OLD.kind AND NEW.step=OLD.step AND NEW.call_item_id<=>OLD.call_item_id AND NEW.ordinal=OLD.ordinal AND JSON_REMOVE(NEW.record_json,'$.state','$.usage','$.usageId','$.completedAtMs')=JSON_REMOVE(OLD.record_json,'$.state','$.usage','$.usageId','$.completedAtMs') AND (OLD.state='admitted' OR NEW.record_json=OLD.record_json)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Subagent budget settlement is invalid'; END IF; END;

